const input = $input.first().json;
if (!input.headers?.['x-workflow-token'] || input.headers['x-workflow-token'] !== $env.N8N_WEBHOOK_TOKEN) throw new Error('Unauthorized workflow trigger.');
const body = input.body ?? {};
for (const key of ['request_id', 'question_id', 'site_key', 'workflow_key', 'workflow_version']) { if (!body[key]) throw new Error(`Missing ${key}.`); }
return [{ json: body }];

const context = $input.first().json.context;
const system = `You classify one ecommerce product question before drafting a reply. First split the question into every independent clause, including requests joined by and, commas, or then. Return JSON only with: clauses (array of text, intent, status), intents (1-6 unique keys selected only from supported_intents), customer_language (ISO 639-1), country_code (explicit destination only or null), event_date (explicit date in YYYY-MM-DD; resolve a month/day to the next occurrence using current_date), requested_currency, requested_language, requires_private_reply, unmatched_requests, summary. Every clause must map to an intent or unmatched_requests. Never invent facts. Distinguish product attributes, fit, size chart, plus size, stock, restock, tracking, cancellation policy, actual photos, color photos, and customization intents exactly. Existing-order status, tracking, and refunds are private. Use ask_pockets for whether the item includes pockets and request_add_pockets when the customer asks whether pockets can be added. A combined pockets question may select both. Use request_custom_color only when the customer asks to manufacture an unlisted/custom color; use ask_available_colors for whether a listed color is available. Use request_remove_train for shortening or removing a train. Do not use request_custom_length unless the customer explicitly asks to change the garment length.`;
return [{ json: { system_prompt: system, user_prompt: JSON.stringify(context) } }];

const context = $('Start Draft Request').first().json.context;
const resolved = $('Resolve Product Order and Live Facts').first().json;
const policies = $input.first().json.data;
const system = `Write a customer-service draft for a public ecommerce product Q&A. Return JSON only: answer_en, covered_intents, confidence (0-1), unresolved_facts, safety_flags. Address every planned clause exactly once and list only genuinely answered intents in covered_intents. Use only supplied current facts and verified policies. If a clause cannot be answered safely, state the limitation without inventing a future action. Lead with the direct answer. Be concise: target at most 60 words for a simple question and never exceed 180 words. Do not repeat the product title, product identifier, or product URL. Do not add greetings, filler, internal reasoning, policy names, API details, or a generic contact-us paragraph. Never claim that you, our team, support, a factory, or a human will check, verify, follow up, get back, report back, escalate, or review anything unless an allowed_action and an actual action proposal are supplied. No action proposal is supplied in this workflow. Do not turn a missing field into a negative fact. Do not promise delivery, availability, customization, refunds, or payment outcomes without explicit fact and policy support. Never disclose customer or order identifiers. Catalog images are not proof of an actual-product or real-color photo. Existing-order, tracking, and refund questions must remain private. For pockets, follow the verified default and silhouette policies. Keep English and later translations semantically equivalent.`;
const user = JSON.stringify({ question: context.question, customer_language: resolved.plan.customer_language, clauses: resolved.plan.clauses, intents: resolved.plan.intents, unmatched_requests: resolved.plan.unmatched_requests, facts: resolved.facts, missing_facts: resolved.missing, safety_flags: resolved.safety_flags, recommended_visible: resolved.recommended_visible, policies, allowed_actions: context.allowed_actions, reply_style: context.reply_style });
return [{ json: { system_prompt: system, user_prompt: user } }];

const plan = $('Resolve Product Order and Live Facts').first().json.plan;
const draft = $input.first().json.output;
const system = `Translate the supplied English customer-service draft into target_language. Return JSON only: answer_localized. Preserve meaning, factual limits, brevity, product numbers, links, and safety wording. Do not add information. If target_language is en, return the English text unchanged.`;
return [{ json: { system_prompt: system, user_prompt: JSON.stringify({ target_language: plan.customer_language, answer_en: draft.answer_en }) } }];

const context = $('Start Draft Request').first().json.context;
const resolved = $('Resolve Product Order and Live Facts').first().json;
const policies = $('Load Verified Policies').first().json.data;
const generated = $('Generate English Draft').first().json.output;
const translated = $input.first().json.output;
const system = `Act only as a safety, factuality, policy, clause-completeness, and customer-tone reviewer. Do not rewrite the answer. Return JSON only with: approved, must_block, covered_intents, uncovered_intents, problems, repair_instructions, confidence, safety_flags. Compare every planned clause with the answer. covered_intents must contain only intents materially answered; uncovered_intents must contain every omitted intent. Check supplied facts, verified policies, privacy, catalog-photo versus actual-photo claims, unresolved placeholders, product title or identifier repetition, generic contact referrals, and promises of future human or factory action. If any planned intent is uncovered, set approved=false. If a safe answer is impossible because an essential current fact or verified policy is missing, set must_block=true. A simple answer should normally be about 60 English words and two to four sentences.`;
const user = JSON.stringify({ question: context.question, product_name: resolved.facts?.product?.name ?? null, plan: resolved.plan, facts: resolved.facts, missing_facts: resolved.missing, pre_generation_safety_flags: resolved.safety_flags, recommended_visible: resolved.recommended_visible, policies, allowed_actions: context.allowed_actions, answer_en: generated.answer_en, answer_localized: translated.answer_localized, generated_covered_intents: generated.covered_intents, generated_unresolved_facts: generated.unresolved_facts, generated_safety_flags: generated.safety_flags, reply_style: context.reply_style });
return [{ json: { system_prompt: system, user_prompt: user } }];

const review = $input.first().json;
const context = $('Start Draft Request').first().json.context;
const resolved = $('Resolve Product Order and Live Facts').first().json;
const answer = $('Generate English Draft').first().json.output?.answer_en ?? '';
const policies = $('Load Verified Policies').first().json.data ?? [];
const contactPattern = /\b(?:contact(?:ing)?\s+(?:us|our\s+(?:team|support|customer\s+service))|email\s+us|reach\s+(?:out\s+to\s+)?us)\b|\bsupport@[a-z0-9.-]+\.[a-z]{2,}\b/i;
const policyText = JSON.stringify(policies);
const policyAllowsContact = contactPattern.test(policyText) || policyText.includes('site.customer_service_email');
const productName = resolved.facts?.product?.name ?? '';
const repeatsProductName = productName.length >= 5 && answer.toLocaleLowerCase().includes(productName.toLocaleLowerCase());
const repeatsProductSn = context.product_sn && new RegExp(`\\b${String(context.product_sn).replace(/[.*+?^${}()|[\\]\\]/g, '\\$&')}\\b`, 'i').test(answer);
const problems = [...(review.output?.problems ?? [])];
let instructions = [...(review.output?.repair_instructions ?? [])];
if (!policyAllowsContact) instructions = instructions.filter(instruction => !contactPattern.test(String(instruction)));
if (contactPattern.test(answer) && !policyAllowsContact) {
  problems.push('The answer adds a generic contact referral that is not required by the selected policy.');
  instructions.push('Remove the generic contact or email referral and answer only with the supplied product facts and verified policy.');
}
if (repeatsProductName || repeatsProductSn) {
  problems.push('The answer unnecessarily repeats the product title or identifier.');
  instructions.push('Remove the product title and identifier because the product is already clear from the question context.');
}
const requiresRepair = problems.length > (review.output?.problems ?? []).length || repeatsProductName || repeatsProductSn || (contactPattern.test(answer) && !policyAllowsContact);
return [{ json: { ...review, output: { ...review.output, approved: requiresRepair ? false : review.output?.approved, problems: [...new Set(problems)], repair_instructions: [...new Set(instructions)] } } }];

const review = $input.first().json;
const generated = $('Generate English Draft').first().json.output;
const translated = $('Translate to Target Language').first().json.output;
return [{ json: { output: { approved: true, must_block: review.output.must_block === true, covered_intents: review.output.covered_intents ?? generated.covered_intents ?? [], uncovered_intents: review.output.uncovered_intents ?? [], problems: review.output.problems ?? [], repair_summary: null, final_answer_en: generated.answer_en, final_answer_localized: translated.answer_localized, confidence: review.output.confidence ?? generated.confidence, safety_flags: review.output.safety_flags ?? [] }, usage: { reviewer: review.usage }, request_id: review.request_id } }];

const context = $('Start Draft Request').first().json.context;
const resolved = $('Resolve Product Order and Live Facts').first().json;
const policies = $('Load Verified Policies').first().json.data;
const generated = $('Generate English Draft').first().json.output;
const translated = $('Translate to Target Language').first().json.output;
const review = $input.first().json.output;
const system = `Repair the supplied draft exactly once using the review instructions. Return JSON only with: answer_en, answer_localized, covered_intents, repair_summary, confidence, safety_flags. Cover every planned clause that can be answered and list those intents in covered_intents. Preserve supplied facts and verified policy limits. Do not add new facts, future human or factory actions, promises, product titles, identifiers, product URLs, generic contact referrals, or unresolved placeholders. Keep English and localized answers semantically equivalent.`;
return [{ json: { system_prompt: system, user_prompt: JSON.stringify({ question: context.question, plan: resolved.plan, facts: resolved.facts, missing_facts: resolved.missing, policies, allowed_actions: context.allowed_actions, answer_en: generated.answer_en, answer_localized: translated.answer_localized, review }) } }];

const context = $('Start Draft Request').first().json.context;
const resolved = $('Resolve Product Order and Live Facts').first().json;
const policies = $('Load Verified Policies').first().json.data;
const repaired = $input.first().json.output;
const system = `Perform the final review after one repair. Do not repair again. Return JSON only with: approved, must_block, covered_intents, uncovered_intents, problems, repair_summary, final_answer_en, final_answer_localized, confidence, safety_flags. Compare the final answer against every planned clause. Approve only if every intent is materially covered, all claims follow supplied facts and verified policies, no unsupported future action is promised, privacy is safe, English and localized answers match, and the response is concise and natural. If anything remains unsafe or materially incomplete, set approved=false and must_block=true while preserving the repaired answer for human review.`;
return [{ json: { system_prompt: system, user_prompt: JSON.stringify({ question: context.question, plan: resolved.plan, facts: resolved.facts, missing_facts: resolved.missing, policies, allowed_actions: context.allowed_actions, repaired_answer: repaired }) } }];

const review = $input.first().json;
const context = $('Start Draft Request').first().json.context;
const resolved = $('Resolve Product Order and Live Facts').first().json;
const answer = review.output?.final_answer_en ?? '';
const policies = $('Load Verified Policies').first().json.data ?? [];
const contactPattern = /\b(?:contact(?:ing)?\s+(?:us|our\s+(?:team|support|customer\s+service))|email\s+us|reach\s+(?:out\s+to\s+)?us)\b|\bsupport@[a-z0-9.-]+\.[a-z]{2,}\b/i;
const policyText = JSON.stringify(policies);
const productName = resolved.facts?.product?.name ?? '';
const unsupportedContactReferral = contactPattern.test(answer) && !contactPattern.test(policyText) && !policyText.includes('site.customer_service_email');
const repeatsProductName = productName.length >= 5 && answer.toLocaleLowerCase().includes(productName.toLocaleLowerCase());
const repeatsProductSn = context.product_sn && new RegExp(`\\b${String(context.product_sn).replace(/[.*+?^${}()|[\\]\\]/g, '\\$&')}\\b`, 'i').test(answer);
if (!unsupportedContactReferral && !repeatsProductName && !repeatsProductSn) return [{ json: review }];
const problems = [...(review.output?.problems ?? [])];
const safetyFlags = [...(review.output?.safety_flags ?? [])];
if (unsupportedContactReferral) {
  problems.push('The repaired answer still adds a generic contact referral that is not required by the selected policy.');
  safetyFlags.push('Unsupported generic contact referral remained after the single repair.');
}
if (repeatsProductName || repeatsProductSn) {
  problems.push('The repaired answer still repeats the product title or identifier.');
  safetyFlags.push('Product identity repetition remained after the single repair.');
}
return [{ json: { ...review, output: { ...review.output, approved: false, must_block: true, problems: [...new Set(problems)], safety_flags: [...new Set(safetyFlags)] } } }];
